static void ui_diagnostics45(const Combat*g,const WindowUI*u,unsigned fps,unsigned freeMB,unsigned map,float measured,const char*saveState,unsigned quads){if(g->diagnosticsOff45)return;int x,y;diagnostics_layout200(minimapSize60,&x,&y);(void)u;hud_panel(x,y,210,43);hud_text(x+6,y+1,"%u FPS | %u MB free | Map %u",fps,freeMB,map);int actual=ui_round47a(measured*10),nominal=ui_round47a(combat_walk_speed(g)*10);hud_text(x+6,y+14,"Walk %d.%d / %d.%d",actual/10,actual%10,nominal/10,nominal%10);hud_text(x+6,y+27,"%s | HUD %u quads",saveState,quads);}
